/**
 * "Ilustrado" image source (script.imageSource): instead of searching stock libraries, every beat gets an image
 * generated by the Antigravity CLI (its built-in image tool, plan credits, no API key), always in the same
 * stylized 3D look. Tested on the home PC (2026-10-26): agy answers with the generated file's path, saved under
 * its own "brain" folder (~/.gemini/antigravity-cli/brain/<conversation>/), never in the sandbox cwd.
 *
 * Security: same isolation as the text calls (--sandbox, --disable-slash-commands, empty temp cwd, minimal env,
 * never --dangerously-skip-permissions). The path in the answer is untrusted text: a file is only copied when it
 * resolves inside the brain folder and its first bytes are a JPEG/PNG/WEBP.
 */
import { spawn } from "node:child_process";
import { copyFile, mkdir, mkdtemp, open, realpath, rm } from "node:fs/promises";
import { homedir, tmpdir } from "node:os";
import { join, resolve, sep } from "node:path";
import { minimalChildEnv } from "./childEnv.js";
import { env } from "./config.js";
import { probeVideo } from "./ffmpeg.js";
import type { Logger } from "./logger.js";
import type { FootageClip } from "../types.js";

/** Fixed look of every illustration (the scene description from the script goes in front of it). */
export const ILLUSTRATION_STYLE =
  "stylized 3D low-poly render, clean simple shapes, soft studio lighting, vibrant saturated colors, " +
  "dark gradient background, cinematic, vertical 9:16 composition, stylized characters (not photorealistic), " +
  "no text, no letters, no numbers, no logos, no license plates, no watermark";
export const ILLUSTRATION_SOURCE = "ia-agy";
export const ILLUSTRATION_LICENSE = "gerada por IA";
/** Model of the agent that calls the image tool (the image itself comes from the tool). */
const AGENT_MODEL = "gemini-3.8-flash-low";
/** Measured 58-112 s per call at home (the agent waits for its image sub-agent). */
const TIMEOUT_S = 300;
const CONCURRENCY = 2;
/** Seconds a still is planned for before the render spreads it over its beat (same as stock stills). */
const STILL_SECONDS = 5;

export function brainDir(): string {
  return env("ANTIGRAVITY_BRAIN_DIR") ?? join(homedir(), ".gemini", "antigravity-cli", "brain");
}

export function illustrationPrompt(scene: string): string {
  return [
    "Gere UMA imagem com a sua ferramenta de geração de imagens, proporção 9:16 (vertical), com este prompt em inglês:",
    `"${scene.trim()}. ${ILLUSTRATION_STYLE}"`,
    "Não execute comandos de terminal nem leia arquivos. Responda apenas com o caminho completo do arquivo gerado.",
  ].join("\n");
}

/** Every image-file path mentioned in agy's output (JSON-escaped or plain, with or without file:///). */
export function imagePathsIn(output: string): string[] {
  const text = output.replace(/\\\\/g, "\\").replace(/file:\/\/(?:\/(?=[A-Za-z]:))?/gi, "");
  // No whitespace inside a path: the brain folder lives under the user's home (no spaces in the tested setup).
  const found = text.match(/(?:[A-Za-z]:[\\/]|\/)[^\s"'`<>|()[\]]*?\.(?:jpe?g|png|webp)\b/gi) ?? [];
  return [...new Set(found.map((p) => p.trim()))];
}

export function isInside(dir: string, file: string): boolean {
  const norm = (p: string) => (process.platform === "win32" ? resolve(p).toLowerCase() : resolve(p));
  const root = norm(dir);
  return norm(file).startsWith(root.endsWith(sep) ? root : `${root}${sep}`);
}

export function sniffImage(head: Buffer): "jpg" | "png" | "webp" | undefined {
  if (head.length >= 3 && head[0] === 0xff && head[1] === 0xd8 && head[2] === 0xff) return "jpg";
  if (head.length >= 8 && head.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]))) return "png";
  if (head.length >= 12 && head.subarray(0, 4).toString("latin1") === "RIFF" && head.subarray(8, 12).toString("latin1") === "WEBP") return "webp";
  return undefined;
}

async function readHead(file: string): Promise<Buffer> {
  const handle = await open(file, "r");
  try {
    const buf = Buffer.alloc(16);
    const { bytesRead } = await handle.read(buf, 0, 16, 0);
    return buf.subarray(0, bytesRead);
  } finally {
    await handle.close();
  }
}

function runAgy(prompt: string, cwd: string): Promise<string> {
  const cli = env("ANTIGRAVITY_CLI_PATH") || "agy";
  const args = ["--output-format", "json", "--sandbox", "--disable-slash-commands", "--print-timeout", `${TIMEOUT_S}s`, "--model", AGENT_MODEL];
  return new Promise((resolvePromise, reject) => {
    const child = spawn(cli, args, { cwd, env: minimalChildEnv([], process.env), stdio: ["pipe", "pipe", "pipe"], windowsHide: true });
    let out = "";
    let err = "";
    const timer = setTimeout(() => child.kill("SIGKILL"), (TIMEOUT_S + 30) * 1000);
    child.stdout.on("data", (c: Buffer) => (out += c.toString("utf8")));
    child.stderr.on("data", (c: Buffer) => (err += c.toString("utf8")));
    child.on("error", (e) => {
      clearTimeout(timer);
      reject(e);
    });
    child.on("close", (code) => {
      clearTimeout(timer);
      if (code === 0) resolvePromise(out);
      else reject(new Error(`agy finalizou com código ${code}: ${(err || out).slice(-500)}`));
    });
    child.stdin.end(prompt, "utf8");
  });
}

/** One illustration of `scene` copied to `outBase`.<ext>; throws when agy gave no usable image. */
export async function generateIllustration(scene: string, outBase: string): Promise<string> {
  const cwd = await mkdtemp(join(tmpdir(), "agy-img-"));
  try {
    const output = await runAgy(illustrationPrompt(scene), cwd);
    const brain = brainDir();
    // Last mention wins: the final answer repeats the path after the tool output.
    for (const mentioned of imagePathsIn(output).reverse()) {
      // realpath: a link inside the brain folder must not lead outside it.
      const candidate = await realpath(mentioned).catch(() => undefined);
      if (!candidate || !isInside(await realpath(brain).catch(() => brain), candidate)) continue;
      const ext = await readHead(candidate).then(sniffImage, () => undefined);
      if (!ext) continue;
      const target = `${outBase}.${ext}`;
      await copyFile(candidate, target);
      return target;
    }
    throw new Error(`agy não devolveu caminho de imagem válido dentro de ${brain}: ${output.slice(-300)}`);
  } finally {
    await rm(cwd, { recursive: true, force: true });
  }
}

/** Same contract as the stock adapter: one image clip per query (sceneIndex as given); failures are logged and skipped. */
export async function generateIllustrations(queries: readonly { sceneIndex: number; query: string }[], outDir: string, log: Logger): Promise<FootageClip[]> {
  await mkdir(outDir, { recursive: true });
  const results: (FootageClip | undefined)[] = new Array(queries.length);
  let next = 0;
  const worker = async (): Promise<void> => {
    while (next < queries.length) {
      const i = next++;
      const q = queries[i]!;
      const started = performance.now();
      try {
        const path = await generateIllustration(q.query, join(outDir, `ia_${String(i).padStart(2, "0")}`));
        const probe = await probeVideo(path);
        results[i] = {
          sceneIndex: q.sceneIndex,
          path,
          kind: "image",
          durationSeconds: STILL_SECONDS,
          width: probe.width,
          height: probe.height,
          source: ILLUSTRATION_SOURCE,
          sourceUrl: "",
          creator: "",
          license: ILLUSTRATION_LICENSE,
        };
        log.info(`Illustration ${i + 1}/${queries.length} (scene slot ${q.sceneIndex}) in ${((performance.now() - started) / 1000).toFixed(0)} s: "${q.query}"`);
      } catch (error) {
        log.warn(`Illustration ${i + 1}/${queries.length} failed ("${q.query}"): ${error instanceof Error ? error.message : String(error)}`);
      }
    }
  };
  await Promise.all(Array.from({ length: Math.min(CONCURRENCY, queries.length) }, worker));
  return results.filter((c): c is FootageClip => c !== undefined);
}
